import{_ as e,H as o,f as n,i as r}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"20 | ControlNet：出道即巅峰，构图控制没有对手","description":"","frontmatter":{},"headers":[{"level":2,"title":"初识 ControlNet","slug":"初识-controlnet","link":"#初识-controlnet","children":[]},{"level":2,"title":"ControlNet 算法原理","slug":"controlnet-算法原理","link":"#controlnet-算法原理","children":[{"level":3,"title":"ControlNet 的基本结构","slug":"controlnet-的基本结构","link":"#controlnet-的基本结构","children":[]},{"level":3,"title":"训练 ControlNet","slug":"训练-controlnet","link":"#训练-controlnet","children":[]}]},{"level":2,"title":"ControlNet 的持续进化","slug":"controlnet-的持续进化","link":"#controlnet-的持续进化","children":[{"level":3,"title":"指令级修图","slug":"指令级修图","link":"#指令级修图","children":[]},{"level":3,"title":"Tile 功能","slug":"tile-功能","link":"#tile-功能","children":[]}]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI绘画核心技术与实战/20｜ControlNet：出道即巅峰，构图控制没有对手.md","filePath":"AI绘画核心技术与实战/20｜ControlNet：出道即巅峰，构图控制没有对手.md","lastUpdated":1795562124000}'),l={name:"AI绘画核心技术与实战/20｜ControlNet：出道即巅峰，构图控制没有对手.md"};function i(a,t,E,s,p,h){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_20-controlnet-出道即巅峰-构图控制没有对手" tabindex="-1">20 | ControlNet：出道即巅峰，构图控制没有对手 <a class="header-anchor" href="#_20-controlnet-出道即巅峰-构图控制没有对手" aria-label="Permalink to &quot;20 | ControlNet：出道即巅峰，构图控制没有对手&quot;">​</a></h1><p>你好，我是南柯。</p><p>我们知道 Stable Diffusion 可以用文本引导图像生成。除了使用 prompt 这种比较原始的方式，还有没有控制能力更强的方法呢？</p><p>其实早在第 2 讲，我就留过一个思考题，AI 绘画生成的图像在手部和脸部细节存在瑕疵有哪些解决方式。而我们今天要讲的技术—— ControlNet 就可以解决这个问题，对图像结构做出一定的限制，比如手部的关键点信息、五官信息等。</p><p>2023 年 2 月，ControlNet 这个方法一经提出，便凭借其对于 AI 绘画效果的控制能力火遍全网。最初的 ControlNet 主要用于线稿上色、图像风格化、可控姿态的人体生成等任务。如今各路网友脑洞大开，使用 ControlNet 做出了创意二维码、将文字自然地融入照片等趣味效果。</p><p>这一讲，我们一起来探讨 ControlNet 背后的技术原理和各种应用场景。掌握了 ControlNet 这个“大杀器”，你对于 AI 绘画效果的控制能力会上一个台阶，在下个实战篇实现创意 AI 绘画任务时也会更加得心应手。</p><h2 id="初识-controlnet" tabindex="-1">初识 ControlNet <a class="header-anchor" href="#初识-controlnet" aria-label="Permalink to &quot;初识 ControlNet&quot;">​</a></h2><p>如果说 prompt 是对于 AI 绘画模型指令级的控制，ControlNet 无疑是构图级的控制。为了让你对它建立感性认识，我们先结合一些图片例子，感受一下 ControlNet 的构图控制能力。</p><p>我们首先需要准备一张原始图片，比如一张鹿的照片，我们可以通过图像边缘提取算法获取图像轮廓。把这个轮廓图作为 ControlNet 的输入，同时使用这样一句 prompt “a high-quality,detailed, and professional image”生成图片，便可以得到右侧的四张图片。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/1.png" alt=""></a></p><ul><li>图片来自<a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">https://arxiv.org/abs/2302.05543</a></li></ul><p>这里有两个要点值得我们关注。第一，我们的 prompt 中并不包括任何描述图像内容的信息，便可以得到四张不同鹿的照片。第二，生成的四张照片都满足我们输入的轮廓限制，并且效果各异。</p><p>类似地，我们可以提供建筑的外形线条，通过简单的 prompt 引导，得到各种风格迥异的建筑效果图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/2.png" alt=""></a></p><ul><li>图片来源：<a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">https://arxiv.org/abs/2302.05543</a></li></ul><p>再比如，我们随手画一个草图，比如简单几笔勾勒出乌龟、奶牛和热气球，同样是配合上我们随手写出的 prompt，便可以生成精美的图片。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/3.png" alt=""></a></p><ul><li>图片来自<a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">https://arxiv.org/abs/2302.05543</a></li></ul><p>事实上，ControlNet 可用的控制条件还远不止这些。比如后面这些图，展示的就是使用 HED边缘、人体姿态点、图像分割结果作为控制条件，配合上各种不同 prompt 生成的图像效果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/4.png" alt=""></a></p><ul><li>图片来自<a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">https://arxiv.org/abs/2302.05543</a></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/5.png" alt=""></a></p><ul><li>图片来自<a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">https://arxiv.org/abs/2302.05543</a></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/6.png" alt=""></a></p><ul><li>图片来自<a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">https://arxiv.org/abs/2302.05543</a></li></ul><h2 id="controlnet-算法原理" tabindex="-1">ControlNet 算法原理 <a class="header-anchor" href="#controlnet-算法原理" aria-label="Permalink to &quot;ControlNet 算法原理&quot;">​</a></h2><p>那么，ControlNet 是如何控制生成结果的呢？这就需要我们深入了解它的算法原理了。</p><p>因为 ControlNet 要和 SD 结合起来使用，所以我们先回顾下 SD 模型（为了描述方便，我们接下来都用 SD 来指代 Stable Diffusion）的图像生成过程。你可以看后面这张图，VAE 编码器输出的潜在表示，经过一个 UNet 模型结构便可以完成当前时间步 t 的噪声预测。对于SD1.x 系列，输入的潜在表示和预测得到的噪声都是一个 64x64x4 的向量。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/7.png" alt=""></a></p><p>我们第 9 讲学过的采样器负责在输入的潜在表示上将我们预测的噪声去除，这样便完成了SD 模型的一步去噪。将这个过程重复 N 次（N 是我们的采样步数），我们便可以得到最终潜在表示。这个潜在表示经过 VAE 解码器，便可以生成一张清晰的图像。</p><h3 id="controlnet-的基本结构" tabindex="-1">ControlNet 的基本结构 <a class="header-anchor" href="#controlnet-的基本结构" aria-label="Permalink to &quot;ControlNet 的基本结构&quot;">​</a></h3><p>接下来我们看看 ControlNet 的基本结构。</p><p>ControlNet 并没有改变 SD 模型的 VAE、CLIP 文本编码器和 UNet 结构，而是在这个方案的基础上多加了一些东西。</p><p>后面这张图便是 ControlNet 的算法原理图，红框中的区域是我们熟悉的 SD 模型，绿框中的区域便是 ControlNet 模型。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/8.png" alt=""></a></p><p>SD 部分带有锁的标志表示在 ControlNet 模型的训练过程中，SD 模型的权重不进行更新。为什么要这样做呢？</p><p>有两个原因。第一，ControlNet 作为一个即插即用的插件，训练过程应该避免影响到 SD 模型的部分。第二，固定 SD 权重可以减少一半以上的可学习参数，这么做能节省计算资源。</p><p>也就是说，训练 ControlNet 的前提是，我们手中已经拥有了一个训练完成的 SD 模型，比如SD1.5 这样的预训练模型。ControlNet 的训练目标是得到绿框中新增的模型权重。</p><p>那么，为了实现通过条件控制图像生成这一目的，ControlNet 这个插件模型该怎么设计呢？</p><p>我们需要考虑三个问题。</p><ol><li><p>如何设计 ControlNet 的模型结构。</p></li><li><p>控制条件该怎么输入。</p></li><li><p>ControlNet 和 SD 模型之间的信息要如何交互。</p></li></ol><p>先来看第一个问题，如何设计 ControlNet 的模型结构。要回答这个问题，我们还需要再回顾一下前面的 ControlNet 算法原理图。</p><p>红框中 SD 模型部分展示的是我们熟悉的 UNet 结构，我们能看到，这里的 UNet 由 12 个编码器模块、1 个中间模块和 12 个解码器模块构成。Prompt 的文本表征和时间步 t 的编码都直接作用于这些模块。更多细节，你可以复习我们课程的第 15 讲。</p><p>为了能够对齐控制信号和 SD 特征之间的维度，ControlNet 部分直接拷贝了 UNet 的 12 个编码器模块和中间模块的权重，并加入了 14 个名为零卷积（zero convolution）的层。需要注意的是，prompt 的文本表征和时间步 t 的编码同样作用于 ControlNet 部分的 UNet 编码模块。零卷积的作用我们等会再讨论。</p><p>理解了 ControlNet 的模型结构设计之后，我们再来看第二个问题，ControlNet 的控制条件该如何输入。我们知道，SD 模型 UNet 部分的输入是潜在表示，而 ControlNet 的输入是我们使用的控制条件，比如图像轮廓、手绘线稿等。</p><p>潜在表示是经过 VAE 编码器处理后的特征，分辨率是 64x64x4。而 ControlNet 的输入，比如我们提供的目标轮廓线，通常是 512x512 这样的图像。这样 ControlNet 的控制信号和 SD 模型就不一致了，因此我们需要使用一个小型深度学习网络，将 512x512 维度的控制条件转换为 64x64 维度的特征。</p><p>之后，我们再来看第三个问题，处理 ControlNet 和 SD 模型之间的信息交互。</p><p>仔细观察 ControlNet 的方案图你会发现，ControlNet 输入的特征经过一层零卷积层计算后，就会与 SD 模型输入的潜在表示相加。这样，SD 模型便将潜在表示传递给了 ControlNet 模块。而 ControlNet 后面 13 个零卷积层的输出特征，直接和 SD 模型 UNet 部分对应的特征相加，这么做是为了将控制条件引入到 SD 模型。</p><p>了解了 ControlNet 与 SD 模型的关系，最后我们再来看看零卷积的作用。所谓零卷积，就是初始化权重为零的卷积算子。</p><p>之所以要将权重初始化为零，是为了在 ControlNet 训练的第一步，无论控制条件是什么，经过全零卷积后得到的数值都为零。这样，ControlNet 后面 13 个零卷积层的输出特征也全为零，和 SD 模型 UNet 部分对应的特征相加便没有任何效果。</p><p>因为原始的 SD 模型已经在海量数据上充分训练过了，ControlNet 使用零卷积在一开始不会对SD 产生任何影响，这样一来，引入新的 ControlNet 权重仍可以最大程度保留 SD 模型的 AI绘画能力。</p><p>随着 ControlNet 模型的训练，这些初始化为零的权重会根据梯度进行更新，逐渐开始发挥对SD 模型的控制作用。</p><h3 id="训练-controlnet" tabindex="-1">训练 ControlNet <a class="header-anchor" href="#训练-controlnet" aria-label="Permalink to &quot;训练 ControlNet&quot;">​</a></h3><p>搞定了原理，我们再来深入聊一聊该如何训练一个 ControlNet。</p><p>这个过程可以分为两步。</p><p>第一，根据你要使用的控制方法，在你的数据集上生成这些控制条件，比如提取图像边缘轮廓或者提取人体姿态点。</p><p>第二，按照标准的 SD 模型训练流程进行训练，UNet 的输入包括带噪声的潜在表示、时间步 t的编码、prompt 文本表征和 ControlNet 的控制信号。</p><p>与常规 SD 模型的训练不同，UNet 的输入多了一个 ControlNet 的控制信号。值得一提的是，在第 15 讲我们已经知道，标准 SD 训练过程中使用无分类器引导，一般有 10% 的概率会将训练的 prompt 设置为空字符串。而 ControlNet 的训练中，这个概率是 50%！</p><p>这是为了让 SD 模型在预测噪声时，有更多信号源自 ControlNet 的控制信号，而不是 prompt文本表征。说到底，还是为了加强控制。</p><p>在训练 ControlNet 时，针对每一种控制条件需要单独完成。这里的控制条件可以是轮廓线（Canny、HED 等），也可以是法线、深度图等。所以，在 Hugging Face 中我们可以找到 20余种不同的 ControlNet 模型权重。下一讲我们会探讨这些权重的使用方式。</p><h2 id="controlnet-的持续进化" tabindex="-1">ControlNet 的持续进化 <a class="header-anchor" href="#controlnet-的持续进化" aria-label="Permalink to &quot;ControlNet 的持续进化&quot;">​</a></h2><p>前面我们学习了 ControlNet1.0 的算法效果和技术原理。在两个月之后的 2023 年 4 月，ControlNet 又推出了 1.1 版本。1.1 和 1.0 两个版本的设计思路完全相同，不过 1.1 改进了1.0 版本模型的图像生成效果，并推出了几个全新的 ControlNet 模型。</p><p>我精选了其中最有趣的两个新模型，我们一起来看看。</p><h3 id="指令级修图" tabindex="-1">指令级修图 <a class="header-anchor" href="#指令级修图" aria-label="Permalink to &quot;指令级修图&quot;">​</a></h3><p>首先是指令级修图的 ControlNet。比如后面这张风景图片，我们希望转换图片里的季节，就可以通过 prompt 写下“make it winter”。图中的五个冬季效果是使用不同随机种子得到的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/9.png" alt=""></a></p><ul><li>图片来源：<a href="https://github.com/lllyasviel/ControlNet-v1-1-nightly" target="_blank" rel="noreferrer">https://github.com/lllyasviel/ControlNet-v1-1-nightly</a></li></ul><p>再比如后面这个例子，原始照片是一张人像照，我们可以利用 prompt 把绿衬衫的男人换成钢铁侠。可以看到，ControlNet 保持了原始人像轮廓，生成了钢铁侠的效果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/10.png" alt=""></a></p><ul><li>图片来源：<a href="https://github.com/lllyasviel/ControlNet-v1-1-nightly" target="_blank" rel="noreferrer">https://github.com/lllyasviel/ControlNet-v1-1-nightly</a></li></ul><p>有了这个功能，我们不用复杂的 PS，写个 prompt 就能修图。但它背后的原理是怎样的呢？</p><p>其实也并不复杂，只不过在训练 ControlNet 的时候使用了特殊的成对数据，我们看个例子就明白了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/11.png" alt=""></a></p><ul><li>图片来源：<a href="https://github.com/timothybrooks/instruct-pix2pix" target="_blank" rel="noreferrer">https://github.com/timothybrooks/instruct-pix2pix</a></li></ul><p>图片中的文本就是训练 ControlNet 用的 prompt，原始图像作为 ControlNet 的输入条件，而指令修图后的图像作为 SD 模型的目标输出。更多训练细节你有兴趣的话，可以看看这个链接。</p><h3 id="tile-功能" tabindex="-1">Tile 功能 <a class="header-anchor" href="#tile-功能" aria-label="Permalink to &quot;Tile 功能&quot;">​</a></h3><p>Tile 在中文里是瓷砖的意思，字面理解是将图片切分成棋盘格的样式分别处理再拼接。这个功能很强大，因为它可以帮我们补充图像中的细节。</p><p>Tile 功能对于生成超高分辨率的图片（比如 4K 图像）非常有用，比如后面这张图片，我们的prompt 是“a handsome man”，希望 AI 绘画模型帮我们补充各种局部细节。如果是使用传统SD 模型切块生成再合并，每个切块内都会有一个帅哥，拼接起来的画面自然很鬼畜。</p><p>而使用 Tile 功能时，ControlNet 模型的 Tile 功能会先识别当前切片中的图片内容，如果切片内容和 prompt 无关，使用 Tile 功能生成切片内图像的时候就会降低 prompt 对于生成图像的影响。图片中树叶部分的切片经过 Tile 功能的处理，就会变得格外清晰。你可以点开后面的图片查看效果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/12.png" alt=""></a></p><ul><li>图片来源：<a href="https://github.com/lllyasviel/ControlNet-v1-1-nightly" target="_blank" rel="noreferrer">https://github.com/lllyasviel/ControlNet-v1-1-nightly</a></li></ul><p>我们再来看一个超分辨率的例子。比如后面这张图，输入图像是一张 64x64 分辨率的小狗，使用 Tile 功能配合上“dog on grassland”这个 prompt，可以轻松实现图像的 8 倍超分，得到512x512 分辨率的效果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/13.png" alt=""></a></p><ul><li>图片来源：<a href="https://github.com/lllyasviel/ControlNet-v1-1-nightly" target="_blank" rel="noreferrer">https://github.com/lllyasviel/ControlNet-v1-1-nightly</a></li></ul><p>作为对比，如果选择经典的超分算法 Real-ESRGAN，同样是将 64x64 分辨率超分到512x512，得到的效果是后面这个样子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/14.png" alt=""></a></p><ul><li>图片来源：<a href="https://github.com/lllyasviel/ControlNet-v1-1-nightly" target="_blank" rel="noreferrer">https://github.com/lllyasviel/ControlNet-v1-1-nightly</a></li></ul><p>观察图片可以发现，看到超分的效果并不理想。这样的对比也体现了 ControlNet Tile 功能的优势。</p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>今天这一讲我们探讨了 ControlNet 这个强大的 AI 绘画工具，包括它的算法原理、控图效果和最新能力。</p><p>ControlNet 模型需要与预训练好的 SD 模型配合使用。ControlNet 拷贝了原始 SD 模型的 12个编码器模块和中间模块权重，并加入了 14 个零卷积层。在训练过程中，SD 的权重保持不动，仅更新 ControlNet 部分的模型权重。</p><p>此外，我们还探讨了全零卷积这种特殊设计背后的思考，以及它如何用于 SD 模型和ControlNet 模型之间的信息传输。</p><p>之后，我们详细讨论了 ControlNet1.1 两个亮眼的能力：指令级修图和 Tile 功能。有了这两项能力，我们“动动嘴”便可以实现强大的 P 图和超分功能。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E7%BB%98%E7%94%BB%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/20/15.png" alt=""></a></p><p>了解了 ControlNet 的基本原理，下一讲我们便会使用 Control1.0 和 1.1，完成各种有趣的实战项目，比如创意二维码生成、图像风格化等，敬请期待！</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这一讲中我们介绍了 ControlNet 的几种控制条件，比如边缘轮廓、分割图、人体关键点等。你还知道 ControlNet 有哪些控制条件？这些控制条件我们需要通过怎样的方式获得？</p><p>欢迎你在留言区和我交流讨论。如果这一讲对你有启发，也推荐你分享给身边更多同事、朋友。</p>',98)])])}const c=e(l,[["render",i]]);export{B as __pageData,c as default};
